import sys
from collections import Counter

def smallestWindow(S: str, P: str) -> str:
    if len(P) > len(S):
        return "-1"

    p_count = Counter(P)
    required_chars = len(p_count)
    formed = 0
    window_counts = {}

    left = 0
    min_len = float('inf')
    min_start = -1

    for right, char in enumerate(S):
        if char in p_count:
            window_counts[char] = window_counts.get(char, 0) + 1
            if window_counts[char] == p_count[char]:
                formed += 1

        while formed == required_chars:
            current_len = right - left + 1
            if current_len < min_len:
                min_len = current_len
                min_start = left

            left_char = S[left]
            if left_char in p_count:
                window_counts[left_char] -= 1
                if window_counts[left_char] < p_count[left_char]:
                    formed -= 1
            left += 1

    if min_start == -1:
        return "-1"

    return S[min_start:min_start + min_len]

def main():
    s = sys.stdin.readline().strip()
    p = sys.stdin.readline().strip()
    result = smallestWindow(s, p)
    print(result)

if __name__ == "__main__":
    main()
